#!/usr/bin/env node
// Offline negative tests. Fixtures remain inside the requested research directory.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {analyzeDirectory,compareIdentity,normalizeAppId,filetimeMs,normalizeTime,generationEvidence,parseArguments,parseEvidenceJson} from './steam_controller_consumer_evidence.mjs';
const tool=path.join(path.dirname(fileURLToPath(import.meta.url)),'steam_controller_consumer_evidence.mjs');
const args=process.argv.slice(2);let work;
if(args.length===2&&args[0]==='--work-dir')work=path.resolve(args[1]);
else if(args.length)throw Error('Usage: node tools/steam_controller_consumer_evidence_selftest.mjs [--work-dir <research-directory>]');
else work=path.resolve(path.dirname(tool),'../../../../Docs/Research/Sleep/SteamNonSteamRecovery-20261011/ROUND37-ACK-CONSUMER-CONTRACT');
if(!fs.statSync(work).isDirectory())throw Error('Existing research directory required.');
const fixtures=fs.mkdtempSync(path.join(work,'selftest-fixtures-')),tests=[];
function test(name,fn){try{fn();tests.push({name,status:'pass'});}catch(e){tests.push({name,status:'fail',message:e.message});}}
const local='2026-10-14T11:02:00',ms=Date.parse('2026-10-14T03:02:00Z');
const birth=String(BigInt(Date.parse('2026-10-14T03:01:00Z'))*10000n+116444736000000000n);
const gamePath='C:\\Users\\FixtureSecret\\PrivateGame\\Game.exe';
const boot={event:'boot-single-instance-acquired',time:'2026-10-14T11:00:00',pid:9,powerGeneration:1};
const native={event:'input-host-submit-stats',time:local,pid:9,powerGeneration:3,generation:3,runId:'PRIVATE-RUN',epoch:5,hostInstanceId:'PRIVATE-HOST',persona:'steamdeck',ok:true,detail:JSON.stringify({ok:true,runId:'PRIVATE-RUN',epoch:5,persona:'steamdeck',frameOk:100,frameFail:0,neutralOk:1,neutralFail:0,lastSequence:100})};
const wake={implementation:'steam-wake-round33-native-primary-pid-join',generation:3,recordEpoch:ms/1000,gameInput:'not-tested',healthVerified:false,before:{recordEpoch:ms/1000,game:{pid:100,created:birth},steamClient:{pid:8,created:String(BigInt(ms-100000)*10000n+116444736000000000n),identityToken:'PRIVATE-ACCOUNT'},suspendCapture:{targetSelection:{selectedPid:100,selectedCreated:birth,selectedAppid:2399932135,jointBindingVerified:true,nativePrimary:{label:`"${gamePath}"`},ymccSteamJoin:{appid:2399932135,windowsSessionMatched:true}}}}};
function fixture(name,members={}){const dir=path.join(fixtures,name);fs.mkdirSync(dir);for(const [file,value] of Object.entries(members)){const target=path.join(dir,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,typeof value==='string'?value:JSON.stringify(value,null,2)+'\n');}return dir;}
const base={'YeManCC-export-manifest.txt':'exportedAtLocal=2026-10-14T11:32:00\ntimeZoneBiasMinutes=-480\nmsi-controller-visibility.log 1024\n','native-lifecycle.log':[boot,native].map(o=>JSON.stringify(o)).join('\n')+'\n','wake-recovery-last.json':wake,'steam-controller-ui.log':`[2026-10-14 11:02:00] Controller 15 connected, configuring it now...\n[2026-10-14 11:02:00] !! Controller 15 attributes:\n  ProductID: 6401\n  Serial: PRIVATE-SERIAL\n[2026-10-14 11:02:00] Loaded Config for Last Resort Path for App ID 2399932135, Controller 15: C:\\Users\\FixtureSecret\\layout.vdf\n`};
function noConsumption(r){assert.equal(r.conclusions.originalGameInput,'unknown');assert.equal(r.conclusions.continueAcceptance,'unknown');assert.equal(r.conclusions.fourLayerEndToEnd,'unknown');assert.equal(r.layerClaims.find(c=>c.layer==='L4').observation,'unknown');}

test('explicit-input-and-argument-boundary',()=>{assert.throws(()=>parseArguments([]),/explicit/);assert.throws(()=>analyzeDirectory(),/explicit/);assert.throws(()=>parseArguments(['--desktop']),/Unknown/);assert.throws(()=>parseArguments(['--input','a','--input','b']),/Duplicate/);});
test('exact-64-bit-gameid-and-signed-shortcut-appid',()=>{assert.equal(normalizeAppId('10307630032478011392'),'2399932135');assert.equal(normalizeAppId('-1895035161'),'2399932135');assert.equal(normalizeAppId(10307630032478011392),null);assert.equal(normalizeAppId('18446744073709551616'),null);});
test('FILETIME-string-only-exactness',()=>{assert.equal(filetimeMs(birth),Date.parse('2026-10-14T03:01:00Z'));assert.equal(filetimeMs(Number(birth)),null);});
test('same-PID-different-birth-is-contradicted',()=>{const j=compareIdentity({pid:100,birth:'a',path:'x'},{pid:100,birth:'b',path:'x'},['pid','birth','path']);assert.equal(j.status,'contradicted');assert.deepEqual(j.conflictingAxes,['birth']);});
test('PID-coincidence-with-missing-birth-path-session-is-unknown',()=>assert.equal(compareIdentity({pid:100,birth:'a',path:'x',session:1},{pid:100},['pid','birth','path','session']).status,'unknown'));
test('local-UTC-offset-and-conflict',()=>{assert.equal(normalizeTime({time:local},480).utcEpochMs,ms);assert.equal(normalizeTime({time:local},null).status,'unknown');assert.equal(normalizeTime({time:local,utcEpochMs:ms+10000},480).status,'contradicted');});
test('generation-equality-never-merges-source-namespaces',()=>{const a=generationEvidence({event:'msi-transition',generation:3},'native-detail.log','life',true)[0],b=generationEvidence({event:'request',generation:3},'app.log','life',true)[0];assert.notEqual(a.namespace,b.namespace);assert.equal(a.status,'unknown');assert.equal(b.status,'unknown');const shared=generationEvidence({event:'ack',powerGeneration:3},'native-lifecycle.log','life',true)[0];assert.equal(shared.status,'bound-shared-wake');assert.equal(generationEvidence({powerGeneration:3},'native-lifecycle.log',null,true)[0].status,'unknown');});
test('host-ACK-plus-Steam-config-never-proves-game-input',()=>{const r=analyzeDirectory(fixture('host-only',base));noConsumption(r);assert.equal(r.coverage.L2.observations,0);const e=r.evidence.find(e=>e.kind==='input-host-submit-stats');assert.equal(e.hostTupleAssociation.status,'matched');assert.equal(e.originalInstance.status,'unknown');assert.equal(r.originalInstances[0].identity.sharedWakeNamespace,null);assert.equal(r.missingContracts[0].declaredButAbsentFromExplicitInput.length,1);});
test('equal-generic-generations-in-native-output-and-recovery-are-unknown',()=>{const a={...native};delete a.powerGeneration;const r=analyzeDirectory(fixture('generation-collision',{...base,'native-lifecycle.log':[boot,a].map(o=>JSON.stringify(o)).join('\n')+'\n'}));const e=r.evidence.find(e=>e.kind==='input-host-submit-stats');assert.equal(e.identity.powerGeneration,null);assert.equal(e.identity.sharedWakeNamespace,null);assert.equal(e.identity.generationEvidence[0].value,3);assert.equal(e.identity.generationEvidence[0].status,'unknown');assert.equal(e.hostTupleAssociation.status,'unknown');assert.equal(e.originalInstance.status,'unknown');noConsumption(r);});
test('same-power-number-on-a-new-YMCC-lifetime-cannot-share-a-tuple',()=>{const second={...boot,time:'2026-10-14T11:03:00'},a={...native,time:'2026-10-14T11:04:00'};const r=analyzeDirectory(fixture('pid-reuse',{...base,'native-lifecycle.log':[boot,native,second,a].map(o=>JSON.stringify(o)).join('\n')+'\n'}));const e=r.evidence.filter(e=>e.kind==='input-host-submit-stats');assert.equal(e.length,2);assert.notEqual(e[0].identity.sharedWakeNamespace,e[1].identity.sharedWakeNamespace);assert(!e[0].hostTupleAssociation.evidenceIds.includes(e[1].id));});
test('mismatching-host-inner-tuple-is-contradicted',()=>{const a={...native,detail:JSON.stringify({runId:'OTHER',epoch:5,persona:'steamdeck',frameOk:999})};const r=analyzeDirectory(fixture('tuple-mismatch',{...base,'native-lifecycle.log':[boot,a].map(o=>JSON.stringify(o)).join('\n')+'\n'}));const e=r.evidence.find(e=>e.kind==='input-host-submit-stats');assert.equal(e.observation,'contradicted');assert.equal(e.hostTupleAssociation.status,'unknown');noConsumption(r);});
test('tracker-64-bit-id-matches-app-but-not-process-birth',()=>{const r=analyzeDirectory(fixture('tracker',{...base,'steam-gameprocess.log':`[2026-10-14 11:00:30] AppID 10307630032478011392 adding PID 99 as a tracked process "${gamePath}"\n[2026-10-14 11:02:00] AppID 10307630032478011392 adding PID 100 as a tracked process "${gamePath}"\n`}));const e=r.evidence.filter(e=>e.kind==='steam-gameprocess-track');assert.equal(e[0].originalInstance.status,'contradicted');assert.equal(e[1].identity.appId,'2399932135');assert.equal(e[1].originalInstance.status,'unknown');assert(e[1].originalInstance.missingAxes.includes('gameCreated'));noConsumption(r);});
test('Steam-mirrors-are-deduplicated-with-exact-origins',()=>{const r=analyzeDirectory(fixture('mirrors',{...base,'steam/logs/controller_ui.txt':base['steam-controller-ui.log']}));const cfg=r.evidence.filter(e=>e.kind==='steam-config-selection');assert.equal(cfg.length,1);assert.equal(cfg[0].sources.length,2);const c=r.evidence.find(e=>e.kind==='steam-controller-connection');assert(c.sources.some(s=>s.role==='controller-serial-attribute'&&s.line===4));});
test('privacy-retains-references-but-not-user-path-serial-host-run-account',()=>{const r=analyzeDirectory(fixture('privacy',base));const t=JSON.stringify(r);for(const secret of ['FixtureSecret','PRIVATE-SERIAL','PRIVATE-RUN','PRIVATE-HOST','PRIVATE-ACCOUNT'])assert(!t.includes(secret),secret);for(const e of r.evidence)for(const s of e.sources){assert(Number.isInteger(s.line)&&s.line>0);assert.equal(s.sha256.length,64);}const document=r.evidence.find(e=>e.kind==='captured-original-instance');assert.equal(document.sources[0].jsonPointer,'/before/suspendCapture/targetSelection');});
test('independent-OS-change-is-not-Steam-or-game-consumption',()=>{const r=analyzeDirectory(fixture('os-reader',{...base,'msi-controller-visibility.log':[{event:'start',observerPid:77,parentPid:9,parentCreationTime:'123456789',wakeGeneration:3,utcEpochMs:ms,readOnly:true,writesHardware:false},{event:'dinput',observerPid:77,utcEpochMs:ms+1,inventoryId:1,stateApiSucceeded:true,decodedContentChanged:true,path:'PRIVATE-DEVICE'}].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert.equal(r.coverage.L2.observations,2);for(const e of r.evidence.filter(e=>e.layer==='L2')){assert.equal(e.identity.sharedWakeNamespace,null);assert.equal(e.originalInstance.status,'unknown');assert.equal(e.facts.freshPhysicalActionVerified,false);}noConsumption(r);});
test('generic-power-field-in-an-API-log-cannot-spoof-common-native-schema',()=>{const r=analyzeDirectory(fixture('api-generation',{...base,'app.log':JSON.stringify({...native,command:'API_REQUEST',powerGeneration:3})+'\n'}));const e=r.evidence.filter(e=>e.kind==='input-host-submit-stats').find(e=>e.sources.some(s=>s.file==='app.log'));assert(e);assert.equal(e.identity.sharedWakeNamespace,null);assert.equal(e.hostTupleAssociation.status,'unknown');noConsumption(r);});
test('untrusted-positive-game-consumer-claim-remains-unknown',()=>{const r=analyzeDirectory(fixture('spoof-game',{...base,'game-consumer-receipts.log':JSON.stringify({event:'game-consumer-receipt',gamePid:100,gameCreated:birth,powerGeneration:3,time:local,gameInputVerified:true,continueButtonVerified:true})+'\n'}));assert(r.evidence.some(e=>e.kind==='unverified-consumer-claim'));noConsumption(r);});
test('malformed-and-offset-conflict-are-not-positive',()=>{const dir=fixture('malformed',{...base,'native-lifecycle.log':JSON.stringify(boot)+'\n{broken\n','wake-recovery-current.json':'{bad'});const r=analyzeDirectory(dir,{utcOffsetMinutes:0});assert(r.diagnostics.some(d=>d.kind==='utc-offset-conflict'&&d.status==='contradicted'));assert(r.diagnostics.some(d=>d.kind==='malformed-json-lines'));assert(r.diagnostics.some(d=>d.kind==='malformed-json-document'));noConsumption(r);});
test('backwards-source-clock-is-contradicted',()=>{const r=analyzeDirectory(fixture('clock-regression',{...base,'native-lifecycle.log':[boot,native,{...native,time:'2026-10-14T11:01:50'}].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert(r.diagnostics.some(d=>d.kind==='source-lifetime-clock-regression'));});
test('generic-first-and-sustained-generation-collision-does-not-link',()=>{const first={event:'wake-input-chain-first-frame',time:local,pid:9,generation:3},sustained={event:'wake-input-chain-sustained',time:local,pid:9,generation:3,acceptedSinceBoot:999};const r=analyzeDirectory(fixture('generic-sustained',{...base,'native-lifecycle.log':[boot,first,sustained].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert(!r.diagnostics.some(d=>d.kind==='sustained-on-first-generation-frame'));for(const e of r.evidence.filter(e=>e.layer==='L1'))assert.equal(e.identity.sharedWakeNamespace,null);});
test('explicit-shared-schema-binds-first-and-sustained-within-lifetime',()=>{const first={event:'wake-input-chain-first-frame',time:local,pid:9,powerGeneration:3,generation:999},sustained={event:'wake-input-chain-sustained',time:local,pid:9,powerGeneration:3,generation:999,acceptedSinceBoot:999};const r=analyzeDirectory(fixture('explicit-sustained',{...base,'native-lifecycle.log':[boot,first,sustained].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert(r.diagnostics.some(d=>d.kind==='sustained-on-first-generation-frame'));assert.equal(r.evidence.find(e=>e.kind==='wake-input-chain-first-frame').identity.sharedWakeGeneration,3);});
test('empty-input-is-unknown-without-fallback-discovery',()=>{const r=analyzeDirectory(fixture('empty'));assert.equal(r.files.length,0);assert.equal(r.evidence.length,0);noConsumption(r);});
test('symlinked-member-outside-explicit-input-is-rejected',()=>{const outside=fixture('external',{'logs/controller.txt':'private'}),inside=fixture('symlink');fs.symlinkSync(outside,path.join(inside,'steam'),'junction');assert.throws(()=>analyzeDirectory(inside),/escapes/);});
test('CLI-missing-input-output-replacement-and-input-write-refused',()=>{const missing=spawnSync(process.execPath,[tool],{encoding:'utf8'});assert.equal(missing.status,1);assert.match(missing.stderr,/explicit/);const dir=fixture('cli',base),occupied=path.join(fixtures,'occupied.json');fs.writeFileSync(occupied,'DO-NOT-OVERWRITE');let p=spawnSync(process.execPath,[tool,'--input',dir,'--output',occupied],{encoding:'utf8'});assert.equal(p.status,1);assert.equal(fs.readFileSync(occupied,'utf8'),'DO-NOT-OVERWRITE');p=spawnSync(process.execPath,[tool,'--input',dir,'--output',path.join(dir,'output.json')],{encoding:'utf8'});assert.equal(p.status,1);assert(!fs.existsSync(path.join(dir,'output.json')));});
test('schema-2-explicit-current-count-is-not-legacy-sustained-claim',()=>{const first={event:'wake-input-chain-first-frame',time:local,pid:9,powerGeneration:3,inputChainEvidenceSchema:2,countPowerGeneration:3,sampledHostEpoch:5,acceptedInCurrentGeneration:1,gameInputUnverified:true},sustained={...first,event:'wake-input-chain-sustained',acceptedInCurrentGeneration:50,nonNeutralAcceptedInCurrentGeneration:2};const r=analyzeDirectory(fixture('schema2',{...base,'native-lifecycle.log':[boot,first,sustained].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert(!r.diagnostics.some(d=>d.kind==='sustained-on-first-generation-frame'));assert.equal(r.evidence.find(e=>e.kind==='wake-input-chain-sustained').facts.acceptedInCurrentGeneration,50);noConsumption(r);});
test('schema-2-sample-common-field-conflict-is-contradicted',()=>{const a={...native,inputChainEvidenceSchema:2,countPowerGeneration:999};const r=analyzeDirectory(fixture('schema2-conflict',{...base,'native-lifecycle.log':[boot,a].map(o=>JSON.stringify(o)).join('\n')+'\n'}));assert.equal(r.evidence.find(e=>e.kind==='input-host-submit-stats').observation,'contradicted');noConsumption(r);});
test('independent-reader-start-without-read-is-unknown',()=>{const r=analyzeDirectory(fixture('os-start-only',{...base,'msi-controller-visibility.log':JSON.stringify({event:'start',observerPid:77,parentPid:9,wakeGeneration:3,utcEpochMs:ms})+'\n'}));assert.equal(r.coverage.L2.apiReadObservations,0);assert.equal(r.layerClaims.find(c=>c.layer==='L2').observation,'unknown');noConsumption(r);});
test('second-resolution-Steam-time-overlapping-birth-stays-unknown',()=>{const w=structuredClone(wake);w.before.suspendCapture.targetSelection.selectedCreated=String(BigInt(ms+974)*10000n+116444736000000000n);w.before.game.created=w.before.suspendCapture.targetSelection.selectedCreated;const r=analyzeDirectory(fixture('timestamp-precision',{...base,'wake-recovery-last.json':w,'steam-gameprocess.log':`[2026-10-14 11:02:00] AppID 10307630032478011392 adding PID 100 as a tracked process "${gamePath}"\n`}));const e=r.evidence.find(e=>e.kind==='steam-gameprocess-track');assert.equal(e.time.precisionMs,1000);assert.equal(e.originalInstance.status,'unknown');assert.equal(e.originalInstance.temporalStatus,'timestamp-precision-overlaps-original-creation');});

// Round37: only native local ACK tuple provenance; all consumer claims remain unknown.
const ackFast={schema:1,authority:'native-local-ack-diagnostic',nativeAccepted:true,tupleVerified:true,status:'verified-local-ack',identityOrigin:'strict-fast-validator-equality-and-parsed-host',gameInputUnverified:true,steamConsumptionProven:false,requestBindingCapturedBeforeRequest:true,protocolPowerGeneration:1,hostEpoch:5,wireSequence:101,runId:'PRIVATE-ACTUAL-RUN',hostInstanceId:'PRIVATE-ACTUAL-HOST',requestId:'PRIVATE-ACTUAL-REQUEST',protocolGenerationScope:'input-host-bound-protocol;not-current-shared-power'};
const ackRow={event:'wake-input-chain-first-frame',time:local,pid:9,powerGeneration:3,inputChainEvidenceSchema:3,countPowerGeneration:3,sampledHostEpoch:999,acceptedInCurrentGeneration:1,ackIdentity:ackFast};
function ackFixture(name,a=ackFast,changes={},prefix=[boot]) {
 const row={...ackRow,...changes,ackIdentity:a};
 const r=analyzeDirectory(fixture(name,{...base,'native-lifecycle.log':[...prefix,row].map(o=>JSON.stringify(o)).join('\n')+'\n'}));
 noConsumption(r);return {r,e:r.evidence.find(e=>e.kind==='wake-input-chain-first-frame')};
}
test('R37-fast-valid-tuple-separate-from-current-power-and-epoch',()=>{const {r,e}=ackFixture('r37-fast');assert.equal(e.facts.ackIdentity.status,'verified-local-ack');assert.equal(e.protocolHostAssociation.status,'matched');assert.equal(e.facts.ackIdentity.protocolTuple.protocolPowerGeneration,1);assert.equal(e.identity.sharedWakeGeneration,3);assert.equal(e.facts.sampledHostEpoch,999);assert.equal(e.observation,'observed');assert.equal(e.originalInstance.status,'unknown');assert.equal(r.coverage.L2.observations,0);assert(!JSON.stringify(r).includes('PRIVATE-ACTUAL-'));assert.equal(r.missingContracts.find(c=>c.kind==='wake-frame-tuple-identity').status,'observed');});
test('R37-DOM-valid-local-tuple-is-not-actual-game-consumption',()=>{const {e}=ackFixture('r37-dom',{...ackFast,identityOrigin:'existing-validator-and-parsed-dom-reply'});assert.equal(e.facts.ackIdentity.status,'verified-local-ack');assert.equal(e.facts.ackIdentity.identityOrigin,'existing-validator-and-parsed-dom-reply');assert.equal(e.protocolHostAssociation.status,'matched');});
test('R37-schema-boolean-and-quoted-types-do-not-authorize-tuple',()=>{for(const value of [true,false,'1',2,null]){const {e}=ackFixture('r37-schema-'+String(value),{...ackFast,schema:value});assert.equal(e.facts.ackIdentity.status,'unknown');assert.equal(e.protocolHostAssociation.status,'unknown');}const {e}=ackFixture('r37-producer-schema-string',ackFast,{inputChainEvidenceSchema:'3'});assert.equal(e.facts.ackIdentity.status,'unknown');});
test('R37-boolean-strings-and-other-types-remain-unknown',()=>{for(const key of ['nativeAccepted','tupleVerified','gameInputUnverified','steamConsumptionProven'])for(const value of ['true',1,null]){const {e}=ackFixture('r37-type-'+key+'-'+String(value),{...ackFast,[key]:value});assert.equal(e.facts.ackIdentity.status,'unknown');assert.equal(e.facts.ackIdentity.protocolTuple,null);}});
test('R37-missing-and-wrong-endpoint-ID-types-remain-unknown',()=>{for(const key of ['runId','hostInstanceId','requestId'])for(const [index,value] of [undefined,'',42,{},[]].entries()){const {e}=ackFixture('r37-id-'+key+'-'+index,{...ackFast,[key]:value});assert.equal(e.facts.ackIdentity.status,'unknown');assert.equal(e.protocolHostAssociation.status,'unknown');}});
test('R37-request-binding-origin-authority-and-scope-required',()=>{for(const [key,value] of [['requestBindingCapturedBeforeRequest',false],['identityOrigin','host-self-report'],['authority','InputHost'],['protocolGenerationScope','shared-power'],['status','frame-accepted']]){const {e}=ackFixture('r37-binding-'+key,{...ackFast,[key]:value});assert.equal(e.facts.ackIdentity.status,'unknown');}});
test('R37-current-sampled-outer-host-IDs-do-not-replace-protocol-IDs',()=>{const {e}=ackFixture('r37-sampled-ids',ackFast,{runId:'PRIVATE-SAMPLED-RUN',hostInstanceId:'PRIVATE-SAMPLED-HOST',hostEpoch:999});assert.equal(e.facts.ackIdentity.status,'verified-local-ack');assert.notEqual(e.identity.hostToken,e.facts.ackIdentity.protocolTuple.hostToken);assert.equal(e.observation,'observed');});
test('R37-unknown-reject-and-null-projection-do-not-borrow-endpoints',()=>{for(const [name,a,status] of [['unknown',{...ackFast,tupleVerified:false,status:'unknown',identityOrigin:'none'},'unknown'],['reject',{...ackFast,nativeAccepted:false,tupleVerified:false,status:'not-accepted',identityOrigin:'none'},'not-accepted'],['null',null,'unknown']]){const {e}=ackFixture('r37-'+name,a);assert.equal(e.facts.ackIdentity.status,status);assert.equal(e.facts.ackIdentity.protocolTuple,null);assert.equal(e.protocolHostAssociation.status,'unknown');}});
test('R37-self-conflicting-reject-verified-claim-is-contradicted',()=>{const {e}=ackFixture('r37-contradicted',{...ackFast,nativeAccepted:false});assert.equal(e.facts.ackIdentity.status,'contradicted');assert.equal(e.observation,'contradicted');assert.equal(e.protocolHostAssociation.status,'unknown');});
test('R37-u64-numeric-types-and-range-enforced',()=>{for(const key of ['protocolPowerGeneration','hostEpoch','wireSequence'])for(const value of [0,-1,1.5,'5',true]){const {e}=ackFixture('r37-u64-'+key+'-'+String(value),{...ackFast,[key]:value});assert.equal(e.facts.ackIdentity.status,'unknown');}});
test('exact-JSON-unsafe-numeric-FILETIME-preserves-all-ticks',()=>{const a=parseEvidenceJson('{"birth":134364220808351763}'),b=parseEvidenceJson('{"birth":134364220808351760}');assert.equal(a.birth,'134364220808351763');assert.equal(b.birth,'134364220808351760');assert.equal(compareIdentity(a,b,['birth']).status,'contradicted');assert.throws(()=>parseEvidenceJson('{"birth":1.3436422080835176e17}'),/exact decimal/);});
test('R37-raw-numeric-u64-exact-token-retained-but-quoted-is-wrong-type',()=>{const numeric=JSON.stringify({...ackRow,ackIdentity:{...ackFast,wireSequence:'EXACT_U64'}}).replace('"EXACT_U64"','18446744073709551615'),r=analyzeDirectory(fixture('r37-u64-exact',{...base,'native-lifecycle.log':JSON.stringify(boot)+'\n'+numeric+'\n'}));const e=r.evidence.find(e=>e.kind===ackRow.event);assert.equal(e.facts.ackIdentity.status,'verified-local-ack');assert.equal(e.facts.ackIdentity.protocolTuple.wireSequence,'18446744073709551615');noConsumption(r);const bad=numeric.replace('18446744073709551615','18446744073709551616'),r2=analyzeDirectory(fixture('r37-u64-overflow',{...base,'native-lifecycle.log':JSON.stringify(boot)+'\n'+bad+'\n'}));assert.equal(r2.evidence.find(e=>e.kind===ackRow.event).facts.ackIdentity.status,'unknown');});
