test('L2-same-observer-PID-new-start-does-not-reuse-lifetime',()=>{const r=probeFixture('l2-observer-reuse',[probeStart,probeRead,{...probeStart,utcEpochMs:ms+5000,tick:6000,parentCreationTime:String(BigInt(birth)+1n)},{...probeRead,utcEpochMs:ms+6000,tick:7000}]);assert.equal(r.coverage.L2.apiReadObservations,2);assert.notEqual(r.evidence[1].identity.observerLifetime,r.evidence[3].identity.observerLifetime);assert.notEqual(r.evidence[1].identity.parentCreated,r.evidence[3].identity.parentCreated);noConsumption(r);});
