// R38 owner->observer joins use exact PID/birth; never infer a shared wake or endpoint.
const ownerBirth=String(BigInt(Date.parse('2026-10-14T02:59:00Z'))*10000n+116444736000000000n);
const ownerRecord={schema:1,authority:'native-self-process-identity',pid:boot.pid,creationFiletime:ownerBirth,creationSource:'GetProcessTimes-self',querySucceeded:true,status:'observed',readOnly:true,gameInputUnverified:true,steamConsumptionProven:false};
const ownerBoot={...boot,nativeOwner:ownerRecord};
const ownerStart={...probeStart,parentPid:boot.pid,parentCreationTime:ownerBirth};
const ownerRead={...probeRead,parentPid:boot.pid,parentCreationTime:ownerBirth};
function ownerFixture(name,boots=[ownerBoot],probes=[ownerStart,ownerRead]){return analyzeDirectory(fixture(name,{...base,'native-lifecycle.log':boots.map(o=>JSON.stringify(o)).join('\n')+'\n','msi-controller-visibility.log':probes.map(o=>JSON.stringify(o)).join('\n')+'\n'}));}
const ownerRows=r=>r.evidence.filter(e=>e.layer==='L2');
test('R38-exact-native-parent-owner-matches-only-local-parent',()=>{const r=ownerFixture('r38-exact');for(const e of ownerRows(r)){assert.equal(e.facts.nativeParentRelationship.status,'matched');assert.equal(e.facts.nativeParentRelationship.nativeLifetime,r.nativeOwnerLifetimes[0].nativeLifetime);assert.equal(e.identity.sharedWakeNamespace,null);assert.equal(e.identity.sharedWakeGeneration,null);assert.equal(e.facts.nativeParentRelationship.sharedWakeOwnershipProven,false);}assert.equal(r.coverage.L2.apiReadObservations,1);noConsumption(r);});
test('R38-legacy-boot-without-birth-stays-unknown',()=>{const r=ownerFixture('r38-legacy',[boot]);assert(ownerRows(r).every(e=>e.facts.nativeParentRelationship.status==='unknown'));assert.equal(r.coverage.L2.apiReadObservations,1);noConsumption(r);});
test('R38-exact-one-tick-parent-birth-conflict-stays-distinct',()=>{const r=ownerFixture('r38-one-tick',[{...ownerBoot,nativeOwner:{...ownerRecord,creationFiletime:String(BigInt(ownerBirth)+1n)}}]);assert(ownerRows(r).every(e=>e.facts.nativeParentRelationship.status==='contradicted'));assert.equal(r.coverage.L2.apiReadObservations,1);noConsumption(r);});
