test('R38-native-self-query-failure-keeps-parent-unknown',()=>{const r=ownerFixture('r38-query-fail',[{...ownerBoot,nativeOwner:{...ownerRecord,querySucceeded:false,status:'unknown',creationFiletime:null}}]);assert(ownerRows(r).every(e=>e.facts.nativeParentRelationship.status==='unknown'));noConsumption(r);});
