test('R38-later-same-PID-different-birth-cancels-old-parent-join',()=>{const changed={...ownerBoot,time:'2026-10-14T11:02:00.500',nativeOwner:{...ownerRecord,creationFiletime:String(BigInt(ownerBirth)+1n)}};const r=ownerFixture('r38-later-pid',[ownerBoot,changed]);const rows=ownerRows(r);assert.equal(rows[0].facts.nativeParentRelationship.status,'matched');assert.equal(rows[1].facts.nativeParentRelationship.status,'contradicted');noConsumption(r);});
