// R38 bridge contract fixtures. A schema3 projection on a CREATE command below
// is deliberately synthetic completeness input, NOT something the present
// command logger emits. Real ordinary command fixtures must remain unknown.
const bridgeNames={root:'USB\\VID_045E&PID_028E\\PRIVATE-ROOT-A',rootB:'USB\\VID_045E&PID_028E\\PRIVATE-ROOT-B',hid:'HID\\VID_045E&PID_028E&MI_00\\PRIVATE-HID-A',xbox:'ROOT\\XBOX\\PRIVATE-XBOX-A',sd:'ROOT\\STEAMDECK\\PRIVATE-SD-A',sdHid:'HID\\STEAMDECK\\PRIVATE-SD-HID-A'};
