const roleLists=[[bridgeNames.root],[bridgeNames.xbox],[bridgeNames.hid],[bridgeNames.sd],[bridgeNames.sdHid]];
function pnpDetail(lists=roleLists){return [...bridgeRoles.map(([,count],i)=>count+'='+lists[i].length),'pnp-started=true',...bridgeRoles.map(([ids],i)=>ids+'='+lists[i].map(n=>n+'[PRIVATE-HARDWARE-ID|USB\\PRIVATE-HW]').join(','))].join(';');}
const fullCreate={event:'input-host-command-result',time:local,pid:9,powerGeneration:3,command:'PREPARE_TARGET',phase:'accepted',ok:true,status:'prepared',runId:ackFast.runId,hostInstanceId:ackFast.hostInstanceId,epoch:ackFast.hostEpoch,sequence:ackFast.wireSequence,targetPnpDetail:pnpDetail(),inputChainEvidenceSchema:3,ackIdentity:ackFast};
const ordinaryCreate={...fullCreate};delete ordinaryCreate.inputChainEvidenceSchema;delete ordinaryCreate.ackIdentity;
const diBridge={...ownerRead,event:'directinput-device',utcEpochMs:ms+2000,tick:3000,instanceGuid:'{11111111-2222-3333-4444-555555555555}',interfacePath:'\\\\?\\hid#PRIVATE-DI-INTERFACE#{11111111-2222-3333-4444-555555555555}',interfaceMapping:'directinput-guidandpath',pathHresult:0,pnpInstanceConfigRet:0,pnpInstanceId:bridgeNames.hid,pnpLocateConfigRet:0,usbRootInstance:bridgeNames.root,stateHresult:0};
