// R39: current producer contract and host-local creation lifetime; no device or Steam I/O.
const sdkNs='0123456789abcdef0123456789abcdef';
const sdkLifetime={schema:1,version:1,source:'caller-confirmed-sdk-target-object-lifecycle',state:'live',reason:'sdk-object-created',namespace:'target-creation-local:v1:'+sdkNs,attemptOrdinal:'1',creationOrdinal:'1',lifetimeToken:'target-creation:v1:'+sdkNs+':1',closed:false,closedLifetimeToken:null,closedCreationOrdinal:null,disabled:false,scope:'host-local-SDK-object-creation-lifetime-diagnostic-only',protocolTupleIncluded:false,callerLockScope:'existing-host-lifecycle-lock-required;not-independently-observed',osIncarnationProven:false,sdkOwnershipProven:false,steamConsumptionProven:false,gameInputUnverified:true};
const currentCreate={...fullCreate,ackIdentity:{...fullCreate.ackIdentity,producerScope:'native-lifecycle-command-receipt',command:'PREPARE_TARGET'},targetCreationLifetimeEvidence:sdkLifetime};
const lifetimeFact=r=>r.evidence.find(e=>e.facts.targetCreationLifetime)?.facts.targetCreationLifetime;
test('R39-current-lifecycle-producer-completes-same-row-local-contract-only',()=>{const r=bridgeFixture('r39-current',[currentCreate]),e=r.evidence.find(e=>e.facts.endpointReceipt);assert.equal(e.facts.endpointReceipt.protocolBinding.status,'verified-local-ack-same-row');assert.equal(lifetimeFact(r).status,'reported-live-sdk-object');assert.equal(bridgeCandidates(r)[0].status,'same-device-instance-name-candidate');noConsumption(r);});
test('R39-actual-protocol-power-not-current-shared-power',()=>{const r=bridgeFixture('r39-power',[{...currentCreate,powerGeneration:900}]);assert.equal(lifetimeFact(r).protocolBindingVerified,true);noConsumption(r);});
test('R39-same-tuple-recreate-has-distinct-host-local-object-token',()=>{const next={...currentCreate,command:'RECREATE_TARGET',time:'2026-10-14T11:02:01.100',ackIdentity:{...currentCreate.ackIdentity,command:'RECREATE_TARGET'},targetCreationLifetimeEvidence:{...sdkLifetime,attemptOrdinal:'2',creationOrdinal:'2',lifetimeToken:'target-creation:v1:'+sdkNs+':2',closedLifetimeToken:sdkLifetime.lifetimeToken,closedCreationOrdinal:'1'}},r=bridgeFixture('r39-recreate',[currentCreate,next]);const ls=r.evidence.filter(e=>e.facts.targetCreationLifetime).map(e=>e.facts.targetCreationLifetime);assert.notEqual(ls[0].lifetimeToken,ls[1].lifetimeToken);assert.equal(ls[1].closedLifetimeToken,ls[0].lifetimeToken);assert(ls.every(l=>l.endpointIncarnationProven===false));noConsumption(r);});
test('R39-release-closes-host-object-and-cannot-create-name-candidate',()=>{const closed={...sdkLifetime,state:'closed',closed:true,lifetimeToken:null,closedLifetimeToken:sdkLifetime.lifetimeToken,closedCreationOrdinal:'1'},r=bridgeFixture('r39-release',[{...currentCreate,command:'RELEASE_TARGET',ackIdentity:{...currentCreate.ackIdentity,command:'RELEASE_TARGET'},targetCreationLifetimeEvidence:closed}]);assert.equal(lifetimeFact(r).status,'reported-closed-sdk-object');bridgeUnknown(r);});
